<?php
declare(strict_types=1);
$config=__DIR__.'/openssl-test.cnf';$key=openssl_pkey_new(['private_key_bits'=>2048,'private_key_type'=>OPENSSL_KEYTYPE_RSA,'config'=>$config]);if(!$key)throw new RuntimeException('Could not create test TLS key.');$csr=openssl_csr_new(['commonName'=>'127.0.0.1'],$key,['config'=>$config,'digest_alg'=>'sha256']);$cert=openssl_csr_sign($csr,null,$key,2,['config'=>$config,'x509_extensions'=>'v3_req','digest_alg'=>'sha256'],random_int(1,999999999));if(!$cert)throw new RuntimeException('Could not create test TLS certificate.');openssl_pkey_export($key,$keyPem,null,['config'=>$config]);openssl_x509_export($cert,$certPem);$root=dirname(__DIR__,2);file_put_contents($root.'/.tools/test-key.pem',$keyPem);file_put_contents($root.'/.tools/test-cert.pem',$certPem);echo "Ephemeral localhost TLS certificate created.\n";
